        new_state['location'] = 'garden'
        return new_state
    else:
        print(f"Invalid move from {current} in direction {direction}")
        return state

def take(item_name: str, state: GameState):
    new_state = state.copy()
    if item_name not in state['inventory']:
        new_state['inventory'].append(item_name)
        return new_state
    return new_state

# Predicate definitions for each action
actions = [
    {"name": "ask", "func": ask},
    {"name": "move", "func": move},
    {"name": "take", "func": take},
]

