            params = data['params']
        except:
            raise ValueError("Invalid structured response")

        func_ref = next(a for a in actions if a['name'] == action_name)['func']
        new_state = func_ref(params.get('question'), state) if action_name == 'ask' \
                        else func_ref(params.get('direction'), state) if action_name == 'move' \
                        else func_ref(params.get('item_name'), state)

        return {
            "decision": data,
            "observation": new_state,
            "goal_reached": 'brass_key' in new_state['inventory']
        }

# Game initialization and execution
def main():
    init_state = {
        'location': 'hallway',
        'inventory': [],
        'messages': ["Welcome!"]
    }

    player = AdventurePlayer()
    history = []
    current_state = init_state

    while not current_state['messages'][0].endswith("*KEY FOUND!*"):
        result = player(current_state)
        history.append({
            "step": len(history) + 1,
            "decision": result['decision'],
            "observation": result['observation']
        })
        current_state = result['observation']

    return history

if __name__ == "__main__":
    # Configure dummy LM to simulate deterministic responses
    dspy.configure(
        lm=dspy.utils.DummyLM(script={
            "Initial state": '{"action": "ask", "params": {"question": "where is brass key"}}',
            "Ask response": '{"action": "move", "params": {"direction": "north"}}',
            "Castle visit": '{"action": "take", "params": {"item_name": "brass_key"}}'
        })
    )

    try:
        game_log = main()
        print("\n=== GAME LOG ===")
        for entry in game_log:
            print(f"Step {entry['step']}: Action={json.dumps(entry['decision'])}, Obs Location={entry['observation']['location']}")
    except Exception as e:
        print(f"\nError executing program: {e}")
